SourceCode.Declaration:
/// <summary>
/// Request of the getJobStatus operation: the job ID, or the request ID the job was started with.
/// </summary>
/// <example>
/// { "_request": { "JobId": 5637144576 } } or { "_request": { "RequestId": "pipeline-4711" } }
/// </example>
[DataContractAttribute]
public final class BDRServiceStatusRequest
{
    private RefRecId jobId;
    private BDRRequestId requestId;
    private BDREnvironmentId environmentId;
}

Method.Source:
/// <summary>
/// The job ID that run returned.
/// </summary>
[DataMemberAttribute('JobId')]
public RefRecId parmJobId(RefRecId _jobId = jobId)
{
    jobId = _jobId;
    return jobId;
}

/// <summary>
/// The request ID passed to run; used when no job ID is given.
/// </summary>
[DataMemberAttribute('RequestId')]
public BDRRequestId parmRequestId(BDRRequestId _requestId = requestId)
{
    requestId = _requestId;
    return requestId;
}

/// <summary>
/// Optional environment of the request ID.
/// </summary>
[DataMemberAttribute('EnvironmentId')]
public BDREnvironmentId parmEnvironmentId(BDREnvironmentId _environmentId = environmentId)
{
    environmentId = _environmentId;
    return environmentId;
}
